/**
 * TC-WATCHDOG-028/050/051 golden halves — committed normalized envelopes and
 * text reports for admission, refusal, teardown, and signals-absent.
 *
 * Goldens are regenerated by an explicit command:
 *   WATCHDOG_UPDATE_GOLDENS=1 bun test tests/golden/watchdog-output.test.ts
 * Normalization replaces the temporary repository root and the volatile
 * `runId`/`timing` fields only; branch names, refs, codes, and evidence text
 * survive so a diff stays human-reviewable.
 */
import { describe, expect, test } from "bun:test";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import {
  normalizeEnvelopeText,
  normalizeText,
  runWatchdogCli,
  type WatchdogRun,
} from "../fixtures/watchdog/harness";
import {
  createWatchdogRepository,
  makeClean,
  makeDirty,
  makeOffBase,
  makeSuccessResidue,
  type WatchdogTempRepository,
} from "../fixtures/watchdog/temp-git";
import { ROOT } from "./helpers";

const GOLDEN_ROOT = join(ROOT, "tests/fixtures/watchdog/golden");
const UPDATE = process.env.WATCHDOG_UPDATE_GOLDENS === "1";

type GoldenCase = {
  readonly id: string;
  readonly format: "json" | "text";
  readonly argv: readonly string[];
  readonly setup: (repo: WatchdogTempRepository) => void;
};

const CASES: readonly GoldenCase[] = [
  {
    id: "preflight-clean",
    format: "json",
    argv: ["watchdog", "preflight", "lane-1", "--json"],
    setup: makeClean,
  },
  {
    id: "preflight-dirty",
    format: "json",
    argv: ["watchdog", "preflight", "lane-1", "--json"],
    setup: makeDirty,
  },
  {
    id: "preflight-offbase",
    format: "json",
    argv: ["watchdog", "preflight", "lane-1", "--json"],
    setup: makeOffBase,
  },
  {
    id: "teardown-success",
    format: "json",
    argv: ["watchdog", "teardown", "lane-1", "--json"],
    setup: makeSuccessResidue,
  },
  {
    id: "liveness-absent",
    format: "json",
    argv: ["watchdog", "liveness", "lane-1", "--json"],
    setup: () => {},
  },
  {
    id: "preflight-clean-text",
    format: "text",
    argv: ["watchdog", "preflight", "lane-1"],
    setup: makeClean,
  },
  {
    id: "preflight-dirty-text",
    format: "text",
    argv: ["watchdog", "preflight", "lane-1"],
    setup: makeDirty,
  },
];

const render = (entry: GoldenCase, run: WatchdogRun, repoRoot: string): string =>
  entry.format === "json"
    ? `${JSON.stringify(normalizeEnvelopeText(run, repoRoot), null, 2)}\n`
    : `stdout:\n${normalizeText(run.stdout, repoRoot)}stderr:\n${normalizeText(run.stderr, repoRoot)}`;

describe("TC-WATCHDOG-028/050/051 canonical watchdog goldens", () => {
  for (const entry of CASES) {
    test(`${entry.id} matches its committed golden`, async () => {
      const repo = createWatchdogRepository();
      try {
        entry.setup(repo);
        const run = await runWatchdogCli(entry.argv, { repo });
        const rendered = render(entry, run, repo.directory);
        const path = join(GOLDEN_ROOT, `${entry.id}.${entry.format}`);
        if (UPDATE) {
          mkdirSync(GOLDEN_ROOT, { recursive: true });
          writeFileSync(path, rendered);
          return;
        }
        expect(rendered).toBe(readFileSync(path, "utf8"));
        if (entry.format === "json") {
          expect(rendered).not.toContain(repo.directory);
        }
      } finally {
        repo.remove();
      }
    }, 20_000);
  }
});
